+add_task(async function test_failedMoveRollsBackStorageAndNotifications() {
+  const original = await createEvent();
+  await startEdit(original);
+  changeTitle("Move draft");
+  store.dispatch(
+    updateSection({
+      sessionKey,
+      section: "calendar",
+      patch: { calendarId: destination.id },
+    })
+  );
+  const sourceCalendar = calendar.wrappedJSObject;
+  const deleteItem = sourceCalendar.deleteItem;
+  const checkAndSend = cal.itip.checkAndSend;
+  const notifications = [];
+  const undoStack = [...manager.undoStack];
+  const redoStack = [...manager.redoStack];
+  sourceCalendar.deleteItem = async () => {
+    throw new Error("Source deletion failed");
+  };
+  cal.itip.checkAndSend = (...args) => notifications.push(args);
+  try {
+    Assert.equal((await save()).status, "error");
+    Assert.equal((await calendar.getItem(original.id)).title, "Original");
+    Assert.equal(
+      await destination.getItem(original.id),
+      null,
+      "A failed move removes its destination copy"
+    );
+    Assert.deepEqual(
+      notifications,
+      [],
+      "A failed move sends no invitations or cancellations"
+    );
+    Assert.deepEqual(
+      manager.undoStack,
+      undoStack,
+      "A failed move leaves Undo unchanged"
+    );
+    Assert.deepEqual(
+      manager.redoStack,
+      redoStack,
+      "A failed move leaves Redo unchanged"
+    );
+    Assert.equal(
+      selectCalendarEventDraftState(store.getState(), sessionKey).value.title,
+      "Move draft"
+    );
+    sourceCalendar.deleteItem = deleteItem;
+    Assert.equal(
+      (await save()).status,
+      "success",
+      "The retained draft can retry the move"
+    );
+    Assert.equal(await calendar.getItem(original.id), null);
+    Assert.equal((await destination.getItem(original.id)).title, "Move draft");
+    Assert.deepEqual(
+      notifications.map(args => args[0]),
+      [Ci.calIOperationListener.ADD, Ci.calIOperationListener.DELETE]
+    );
+    await manager.undo();
+    Assert.equal((await calendar.getItem(original.id)).title, "Original");
+    Assert.equal(await destination.getItem(original.id), null);
+    await manager.redo();
+    Assert.equal((await destination.getItem(original.id)).title, "Move draft");
+  } finally {
+    sourceCalendar.deleteItem = deleteItem;
+    cal.itip.checkAndSend = checkAndSend;
+  }
+});
