+add_task(async function test_staleDraftResultsReleaseOnlyTheirOwnRequest() {
+  for (const replace of [false, true]) {
+    for (const fail of [false, true]) {
+      for (const newRequest of [false, true]) {
+        const original = await createEvent();
+        await startEdit(original);
+        changeTitle("Pending title");
+        const started = Promise.withResolvers();
+        const finish = Promise.withResolvers();
+        const pending = save({
+          transact: async (event, oldEvent) => {
+            started.resolve();
+            await finish.promise;
+            if (fail) {
+              throw new Error("Save failed");
+            }
+            await manager.commit(
+              new CalModifyTransaction(event, calendar, oldEvent, {
+                responseMode: Ci.calIItipItem.NONE,
+              })
+            );
+          },
+        });
+        await started.promise;
+        if (replace) {
+          const source = selectCalendarEventSourceSession(
+            store.getState(),
+            sessionKey
+          );
+          store.dispatch(
+            resetFromSource({ sessionKey, snapshot: source.snapshot })
+          );
+          changeTitle("Replacement title");
+        } else {
+          store.dispatch(
+            initializeFields({
+              sessionKey,
+              defaults: {
+                enabledRows: { location: false },
+                reminder: "retained default",
+              },
+            })
+          );
+        }
+        const replacement = selectCalendarEventDraftState(
+          store.getState(),
+          sessionKey
+        );
+        if (newRequest) {
+          store.dispatch(startEditSession({ sessionKey }));
+          store.dispatch(
+            operationStarted({
+              sessionKey,
+              kind: "save",
+              requestId: "replacement-request",
+            })
+          );
+        }
+        const operation = selectCalendarEventCreateEditSession(
+          store.getState(),
+          sessionKey
+        ).operation;
+        finish.resolve();
+        Assert.equal((await pending).status, "stale");
+        Assert.equal(
+          selectCalendarEventDraftState(store.getState(), sessionKey),
+          replacement,
+          "Stale results keep the current draft and defaults"
+        );
+        const currentOperation = selectCalendarEventCreateEditSession(
+          store.getState(),
+          sessionKey
+        ).operation;
+        if (newRequest) {
+          Assert.equal(
+            currentOperation,
+            operation,
+            "A stale result does not release another request"
+          );
+        } else {
+          Assert.equal(
+            currentOperation.status,
+            "idle",
+            "A stale result releases its own pending operation"
+          );
+          Assert.equal(
+            (await save()).status,
+            "success",
+            "The current draft can Save again"
+          );
+        }
+      }
+    }
+  }
+});
